/* Checkpoints are small authored simulations, not live AI characters. */
window.TryvoJourneyPuzzles=(()=>{
 const J=window.TryvoJourney,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let active=null;
 function ensure(d){if(!d.puzzle||typeof d.puzzle!=='object')d.puzzle={};const q=d.puzzle;if(!q.answer||typeof q.answer!=='object'||Array.isArray(q.answer))q.answer={};if(!Array.isArray(q.tries))q.tries=[];q.hint=!!q.hint;q.solved=!!q.solved;return q;}
 function fields(p,a){return p.fields.map(f=>{const key='checkpoint-'+f.key;if(f.type==='checks')return `<fieldset class="puzzle-checks"><legend>${esc(f.label)}</legend>${f.options.map(o=>`<label><input type="checkbox" name="${f.key}" value="${esc(o)}" ${(a[f.key]||[]).includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`;return `<div class="puzzle-field"><label for="${key}">${esc(f.label)}</label>${f.type==='select'?`<select required name="${f.key}" id="${key}"><option value="">Choose…</option>${f.options.map(o=>`<option ${a[f.key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:f.type==='number'?`<input type="number" inputmode="numeric" required step="1" min="${f.min}" max="${f.max}" name="${f.key}" id="${key}" value="${esc(a[f.key]??f.value)}">`:`<textarea required minlength="${f.min}" maxlength="${p.kind==='creative'?240:500}" rows="3" name="${f.key}" id="${key}" placeholder="Use your own words. Avoid personal information.">${esc(a[f.key]||'')}</textarea>`}</div>`;}).join('');}
 function values(form,p){const fd=new FormData(form);return Object.fromEntries(p.fields.map(f=>[f.key,f.type==='checks'?fd.getAll(f.key):fd.get(f.key)||'']));}
 function live(p,a){const n=k=>Number(a[k]||0),meter=(label,val,max)=>`<div><span>${label}</span><strong>${val}</strong><meter min="0" max="${max}" value="${Math.min(max,val)}"></meter></div>`;
 if(p.kind==='distance')return `<div class="puzzle-ledger"><div><span>Your distance saving</span><strong>${n('saved')} km</strong></div>${p.fields.some(f=>f.key==='credits')?`<div><span>Your cost saving</span><strong>${n('credits')} credits</strong></div>`:''}</div><p>Compare the two routes before paying for the detour.</p>`;
 if(p.kind==='balance'){let left=0,right=0;[2,3,5].forEach(w=>{if(a['crate'+w]==='Left')left+=w;if(a['crate'+w]==='Right')right+=w;});return `<div class="cargo-scale" aria-label="Cargo load comparison">${meter('Left shelf',left,10)}<span aria-hidden="true">⚖</span>${meter('Right shelf',right,10)}</div><p>${left===right&&left===5?'Balanced load':'Balance both sides before the bend.'}</p>`;}
 if(p.kind==='negotiation')return `<div class="puzzle-ledger">${meter('Cash needed now',n('fee')+n('deposit'),10)}${meter('Your available cash',7,10)}</div><p>Offer: ${n('fee')} hire + ${n('deposit')} refundable deposit. Return by ${esc(a.return||'—')}.</p>`;
 if(p.kind==='schedule'){const first=n('minute')+8,second=Math.max(first+5,18),finish=second+7;return `<ol class="puzzle-timeline"><li><b>Depot</b>18:${String(n('minute')).padStart(2,'0')}</li><li><b>Musicians</b>18:${String(first).padStart(2,'0')}</li><li><b>Vendors</b>18:${second}</li><li><b>Festival</b>18:${finish}</li></ol><p>${Math.max(0,18-first-5)} minutes waiting at the vendor stop.</p>`;}
 if(p.kind==='allocation')return `<div class="puzzle-ledger">${meter('Tanks assigned',n('aid')+n('kitchen')+n('garden'),15)}${meter('Available tanks',10,15)}</div>`;
 if(p.kind==='market')return `<div class="puzzle-ledger">${meter('Lanterns in your order',n('a')*6+n('b')*10+n('c')*4,40)}${meter('Credits spent',n('a')*6+n('b')*9+n('c')*5,40)}</div>`;
 if(p.kind==='code')return `<div class="relay-digits" aria-label="Your relay code">${['one','two','three'].map(k=>`<span>${esc(a[k]||'—')}</span>`).join('')}</div>`;
 if(p.kind==='creative')return `<div class="announcement-preview"><small>Station display · your draft</small><p>${esc(a.message||'Your words will appear here.')}</p><span>${String(a.message||'').length} / 240 characters</span></div>`;
 if(p.kind==='sequence')return `<ol class="puzzle-timeline">${p.fields.map((f,i)=>`<li><b>${i+1}</b>${esc(a[f.key]||'Choose action')}</li>`).join('')}</ol>`;
 if(p.kind==='assignment')return `<div class="puzzle-ledger">${p.fields.map(f=>`<div><strong>${esc(f.label.replace(' carries',''))}</strong><span>${esc(a[f.key]||'Unassigned')}</span></div>`).join('')}</div>`;
 if(p.kind==='risk')return `<div class="weather-preview"><span>Forecast: 30% rain</span><div class="puzzle-ledger"><div><strong>If dry</strong><span>Exposed: 0 · canopy: 8</span></div><div><strong>If rain</strong><span>Exposed: 30 · canopy: 8</span></div></div><p>Possible outcomes, not a prediction. Decide using the forecast.</p></div>`;
 return `<p>${(a.sources||a.upgrades||[]).length} selected. Your choice is reversible before confirmation.</p>`;
 }
 function open(l,d,api){const q=ensure(d),p=l.puzzle;for(const f of p.fields){if(f.type==='checks')q.answer[f.key]=Array.isArray(q.answer[f.key])?q.answer[f.key].filter(x=>f.options.includes(x)):[];else if(q.answer[f.key]!==undefined&&typeof q.answer[f.key]!=='string'&&typeof q.answer[f.key]!=='number')delete q.answer[f.key];}q.tries=q.tries.filter(t=>t&&typeof t.feedback==='string').slice(-25);active={l,d,api};api.modal(esc(p.title),`<section class="checkpoint-dialog"><div class="checkpoint-speaker"><span class="mira-avatar">${window.TryvoArt.portrait()}</span><div><strong>${esc(p.person)}</strong><small>${esc(p.skill)} checkpoint</small></div></div><p>${esc(p.story)}</p><div class="checkpoint-rules"><strong>The situation</strong><p>${esc(p.rule)}</p></div><form id="checkpoint-form"><div class="puzzle-live" id="puzzle-live"></div><div class="puzzle-fields puzzle-${p.kind}">${fields(p,q.answer)}</div><p class="puzzle-response" id="puzzle-response" role="status">${q.solved?esc(q.feedback||p.win):q.tries.length?esc(q.tries.at(-1).feedback):'Try a plan. You can revise it after feedback.'}</p><div class="checkpoint-actions"><button class="button" type="submit">${p.kind==='negotiation'?'Send my offer':p.kind==='creative'?'Check facts & save':'Test my solution'}</button><button class="button secondary" type="button" data-puzzle-hint>Need a nudge?</button></div><p class="checkpoint-hint" ${q.hint?'':'hidden'}>${esc(p.hint)}</p></form><p class="caption">${esc(p.note||'Authored game rules. Attempts and revisions stay on this device.')}</p><button class="button" data-puzzle-continue ${q.solved?'':'hidden'}>Continue my tram journey →</button></section>`);const form=document.querySelector('#checkpoint-form');if(!Object.keys(q.answer).length)q.answer=values(form,p);document.querySelector('#puzzle-live').innerHTML=live(p,q.answer);document.querySelector('#dialog').classList.add('checkpoint-modal');api.save();}
 function receipt(r){const business=window.TryvoCases?.receipt(r)||'';if(r.puzzle?.case?.review&&!r.puzzle.case.offline)return business;const q=r.puzzle;if(!q)return '<p class="caption">Earlier route record, before checkpoints were added. Preserved without regrading.</p>';const p=r.economyVersion===1?window.TryvoRescueEngine.arrivalPuzzle(window.TryvoRescueEngine.level(r.level),r):J.puzzles[r.level];return business+`<div class="checkpoint-receipt"><strong>${esc(p.title)}</strong><p>${esc(q.feedback||(q.solved?p.win:'Checkpoint not yet resolved.'))}</p><p class="caption">${q.tries?.length||0} checkpoint submissions · ${q.hint?'Nudge used':'No checkpoint nudge used'}</p>${q.solved?`<details><summary>Your checkpoint choices</summary><dl>${p.fields.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(Array.isArray(q.answer[f.key])?q.answer[f.key].join(', '):q.answer[f.key]??'—')}</dd></div>`).join('')}</dl></details>`:''}${q.tries?.length>1?`<details><summary>Earlier checkpoint attempts (${q.tries.length-1})</summary>${q.tries.slice(0,-1).map(t=>`<p>${esc(t.feedback)}</p>`).join('')}</details>`:''}</div>`;}
 document.addEventListener('input',e=>{if(!e.target.closest('#checkpoint-form')||!active)return;const {l,d,api}=active,q=ensure(d);q.answer=values(e.target.form,l.puzzle);q.solved=false;d.lastId=null;api.save();document.querySelector('#puzzle-live').innerHTML=live(l.puzzle,q.answer);document.querySelector('[data-puzzle-continue]').hidden=true;const response=document.querySelector('#puzzle-response');response.textContent='Draft changed. Test this version to check it.';response.classList.remove('is-solved');});
 document.addEventListener('submit',e=>{if(e.target.id!=='checkpoint-form'||!active)return;e.preventDefault();const {l,d,api}=active,q=ensure(d);q.answer=values(e.target,l.puzzle);const result=l.puzzle.grade?l.puzzle.grade(q.answer):J.grade(l.id,q.answer);q.solved=result.ok;q.feedback=result.feedback;q.tries.push({answer:JSON.parse(JSON.stringify(q.answer)),...result,date:new Date().toISOString()});q.tries=q.tries.slice(-25);d.lastId=null;const gained=api.submit?api.submit(result):0;api.save();const response=document.querySelector('#puzzle-response');response.textContent=result.feedback+(result.ok?` ${gained?`+${gained} game points. `:''}${q.reward!==undefined?`${q.reward} travel-credit benefit recorded.`:''}`:'');response.classList.toggle('is-solved',result.ok);document.querySelector('[data-puzzle-continue]').hidden=!result.ok;if(result.ok)document.querySelector('[data-puzzle-continue]').focus();else{response.tabIndex=-1;response.focus();}});
 document.addEventListener('click',e=>{if(!active)return;if(e.target.closest('[data-puzzle-hint]')){active.d.puzzle.hint=true;active.d.hint=true;active.d.lastId=null;document.querySelector('.checkpoint-hint').hidden=false;active.api.save();}if(e.target.closest('[data-puzzle-continue]')){const {d,api}=active;if(!d.puzzle.solved)return;active=null;document.querySelector('#dialog').classList.remove('checkpoint-modal');document.querySelector('#dialog').close();api.continue();}});
 document.querySelector('#dialog').addEventListener('close',()=>{if(!document.querySelector('#dialog').open&&document.querySelector('#checkpoint-form')){document.querySelector('#dialog').classList.remove('checkpoint-modal');if(active)active.api.paint();active=null;}});
 return {open,ensure,receipt};
})();
